def _short_meta(text, limit=158):
    """Keep search snippets concise without cutting a word in half."""
    if len(text) <= limit:
        return text
    return text[:limit + 1].rsplit(" ", 1)[0].rstrip(" ,;:-") + "."


for _service in SERVICES:
    _service["meta_description"] = _short_meta(
        f"{_service['summary']} Explore WeTakeFWD's practical approach for businesses in India."
    )

for _page in SEO_PAGES:
    _page["meta_description"] = _short_meta(_page["meta_description"])
